CREATE TABLE IF NOT EXISTS acore_characters.solazeroth_v3_signalements (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, quand DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, compte INT UNSIGNED NOT NULL, guid INT UNSIGNED NOT NULL, personnage VARCHAR(12) NOT NULL, niveau TINYINT UNSIGNED NOT NULL, carte SMALLINT UNSIGNED NOT NULL, zone INT UNSIGNED NOT NULL, lieu INT UNSIGNED NOT NULL, x FLOAT NOT NULL, y FLOAT NOT NULL, z FLOAT NOT NULL, o FLOAT NOT NULL, cible VARCHAR(80) NOT NULL DEFAULT '', texte TEXT NOT NULL, traite TINYINT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
